contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint amount, uint times) public payable {
        require(address(this).balance >= amount);
        require(times > 0 && times <= 10);

        c.receive{value: amount}();

        uint depositsBefore = c.depositsCount();
        address ownerBefore = c.owner();
        uint cBalBefore = address(c).balance;

        bool reverted = false;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint depositsAfter = c.depositsCount();
        address ownerAfter = c.owner();
        uint cBalAfter = address(c).balance;

        assert(
            (msg.sender == ownerBefore && cBalBefore > 0 && !reverted && cBalAfter == 0) ||
            (msg.sender == ownerBefore && cBalBefore == 0 && reverted && cBalAfter == 0) ||
            (msg.sender != ownerBefore && reverted && cBalAfter == cBalBefore)
        );

        assert(depositsAfter == depositsBefore);
        assert(ownerAfter == ownerBefore);
    }
}

