contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address target, uint value, bytes memory data) public payable {
        // Ignore calls that make the target reject the transfer, so the rule
        // only tests whether owner and balance checks behave as intended.
        (bool ok, ) = target.call{value: 0}("");
        require(ok, "target not callable");

        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        bool reverted;
        try c.sendMoney(target, value, data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // sendMoney can reach its .call only when value <= balance and the owner
        // check passes; in this deployment msg.sender is the owner.  When the
        // call is made with insufficient balance it must revert, otherwise it
        // must complete and send exactly `value` wei while depositsCount stays fixed.
        assert(
            reverted == (value > beforeBalance)
            && afterDeposits == beforeDeposits
            && (
                reverted
                    ? afterBalance == beforeBalance
                    : afterBalance == beforeBalance - value
            )
        );
    }

    receive() external payable {}
}

